/// A version: a struct and a nested table among fixed fields, written whole
@frozen
public struct Box: ~Escapable {
    /// The version of the format, which the header carries and the initializer checks
    public static let formatVersion: UInt32 = 1

    /// The layout that a `Box` is written and read in
    @inlinable
    public static var layout: TableLayout { TableLayout(versioned: true) }

    @usableFromInline
    let _reader: TableReader

    /// Reads a `Box` from `bytes`, which it can't outlive.
    ///
    /// Throws a `DecodeError` if `bytes` are in another format version.
    @inlinable
    @_lifetime(copy bytes)
    public init(_ bytes: RawSpan) throws(DecodeError) {
        _reader = TableReader(bytes, layout: Self.layout)

        let version = try _reader.version
        guard version == Self.formatVersion else {
            throw .unsupportedVersion(version: version, supported: Self.formatVersion)
        }
    }

    /// Returns the format version in the header of `bytes`, without checking it, so that an
    /// application can choose the reader of that version.
    ///
    /// Throws a `DecodeError` if the header doesn't fit in `bytes`.
    @inlinable
    public static func version(of bytes: RawSpan) throws(DecodeError) -> UInt32 {
        try TableReader(bytes, layout: Self.layout).version
    }

    /// Throws a `DecodeError` if the field lies outside the bytes.
    @inlinable
    public var min: Vec2 {
        get throws(DecodeError) {
            let field = try _reader.rootOffset(0)
            return try Vec2(_reader.struct(at: field, size: Vec2.size), at: 0)
        }
    }

    /// Throws a `DecodeError` if the field lies outside the bytes.
    @inlinable
    public var max: Vec2 {
        get throws(DecodeError) {
            let field = try _reader.rootOffset(1)
            return try Vec2(_reader.struct(at: field, size: Vec2.size), at: 0)
        }
    }

    /// Throws a `DecodeError` if the field lies outside the bytes.
    @inlinable
    public var range: Range {
        @_lifetime(copy self)
        get throws(DecodeError) {
            let field = try _reader.rootOffset(2)
            return Range(reader: _reader, position: field)
        }
    }
}

/// The fields of a `Box`, to write
public struct BoxFields: Hashable, Sendable {
    public var min: Vec2
    public var max: Vec2
    public var range: RangeFields

    public init(min: Vec2, max: Vec2, range: RangeFields) {
        self.min = min
        self.max = max
        self.range = range
    }

    /// Writes a `Box` with every field.
    ///
    /// Throws a `BuildError` if it's longer than its offset type, `uint32`, addresses.
    public func serialize() throws(BuildError) -> [UInt8] {
        var sizer = try TableSizer(fields: 3, layout: Box.layout, version: Box.formatVersion)
        sizer.addStruct(size: Vec2.size)
        sizer.addStruct(size: Vec2.size)
        sizer.addTable(alignment: RangeFields.alignment)
        self.range.add(to: &sizer)

        return try sizer.bytes { writer in
            writer.setStruct(0)
            self.min.write(to: &writer)
            writer.setStruct(1)
            self.max.write(to: &writer)
            writer.setTable(2, alignment: RangeFields.alignment)
            self.range.write(to: &writer)
        }
    }
}

