/// The fields of a `Span`, to write
public struct SpanFields: Hashable, Sendable {
    public var name: String
    public var range: RangeFields
    public var frame: FrameFields
    public var ranges: [RangeFields]

    public init(name: String, range: RangeFields, frame: FrameFields, ranges: [RangeFields]) {
        self.name = name
        self.range = range
        self.frame = frame
        self.ranges = ranges
    }

    /// Writes a `Span` with every field.
    ///
    /// Throws a `BuildError` if it's longer than its offset type, `uint32`, addresses.
    public func serialize() throws(BuildError) -> [UInt8] {
        var sizer = try TableSizer(fields: 4, layout: Span.layout)
        sizer.addString(self.name)
        sizer.addTable(alignment: RangeFields.alignment)
        self.range.add(to: &sizer)
        sizer.addTable(alignment: FrameFields.alignment)
        self.frame.add(to: &sizer)
        sizer.addVector(count: self.ranges.count)
        for item in self.ranges {
            item.add(to: &sizer)
        }

        return try sizer.bytes { writer in
            writer.setString(0, self.name)
            writer.setTable(1, alignment: RangeFields.alignment)
            self.range.write(to: &writer)
            writer.setTable(2, alignment: FrameFields.alignment)
            self.frame.write(to: &writer)
            let vector3 = writer.setVector(3, count: self.ranges.count)
            for (index, item) in self.ranges.enumerated() {
                item.write(to: &writer)
                writer.setItemEnd(vector3, item: index)
            }
        }
    }
}

